function scheduleRoadIncidentVideoUpdate(){
 if(roadIncidentVideoFrame)cancelAnimationFrame(roadIncidentVideoFrame);
 roadIncidentVideoFrame=requestAnimationFrame(()=>{roadIncidentVideoFrame=0;syncRoadIncidentVideo(S.logistics);});
}
function syncRoadIncidentVideo(a=S.logistics){
 const show=!!(a&&a.active&&S.step===4&&a.blockedInfo?.length&&a.roadClosurePromptReady!==false&&!document.body.classList.contains('route-camera-stage'));
 let layer=document.getElementById('roadIncidentVideoLayer');
 if(!show){
  document.body.classList.remove('road-incident-video-active');
  const heading=document.querySelector('.logistics-heading');
  if(heading){heading.style.removeProperty('left');heading.style.removeProperty('transform');heading.style.removeProperty('width');}
  if(layer?.classList.contains('show')){layer.classList.remove('show');const video=layer.querySelector('video');video.pause();try{video.currentTime=0;}catch(_){}}
  return;
 }
 layer=ensureRoadIncidentVideoLayer();document.body.classList.add('road-incident-video-active');
 if(M.map&&!roadIncidentVideoBound){M.map.on('move zoom resize',scheduleRoadIncidentVideoUpdate);roadIncidentVideoBound=true;}
 layer.classList.add('show');
 const card=layer.querySelector('.road-incident-video-card'),video=layer.querySelector('video'),link=layer.querySelector('.road-incident-video-line'),svg=layer.querySelector('.road-incident-video-link');
 const width=Math.min(innerWidth<=1100?320:360,innerWidth-24);card.style.width=width+'px';
 const panelRect=document.querySelector('.panel-right')?.getBoundingClientRect();
 let left=innerWidth<=1100?innerWidth-width-12:(panelRect?panelRect.left-width-12:innerWidth-width-18);
 left=Math.max(12,Math.min(innerWidth-width-12,left));
 const heading=document.querySelector('.logistics-heading'),leftPanelRect=document.querySelector('.panel-left')?.getBoundingClientRect();
 if(heading){const available=leftPanelRect?left-(leftPanelRect.right+12)-18:0;if(innerWidth>1100&&available>430){
   const headingLeft=(leftPanelRect.right+12)+'px',headingWidth=Math.min(880,available)+'px';
   if(heading.style.left!==headingLeft)heading.style.left=headingLeft;
   if(heading.style.transform!=='none')heading.style.transform='none';
   if(heading.style.width!==headingWidth)heading.style.width=headingWidth;
  }else{heading.style.removeProperty('left');heading.style.removeProperty('transform');heading.style.removeProperty('width');}}
 const topbarRect=document.querySelector('.topbar')?.getBoundingClientRect(),headingRect=heading?.getBoundingClientRect();
 let top=Math.max(92,(topbarRect?.bottom||56)+32);
 if(headingRect&&left<headingRect.right&&left+width>headingRect.left&&top<headingRect.bottom+12)top=headingRect.bottom+14;
 card.style.left=left+'px';card.style.top=top+'px';
 const cardRect=card.getBoundingClientRect();if(cardRect.bottom>innerHeight-12)card.style.top=Math.max(12,innerHeight-cardRect.height-12)+'px';
 svg.setAttribute('viewBox','0 0 '+innerWidth+' '+innerHeight);svg.setAttribute('width',innerWidth);svg.setAttribute('height',innerHeight);
 const mapWrap=document.getElementById('mapWrap'),blocked=a.blockedInfo[0];let target=null;
 if(M.map&&M.online&&!mapWrap?.classList.contains('fallback')){
  const position=blocked.position||(()=>{const p=wgs2gcj(blocked.lng,blocked.lat);return[p[0],p[1]];})();
  const point=M.map.latLngToContainerPoint(position),rect=M.map.getContainer().getBoundingClientRect();target={x:rect.left+point.x,y:rect.top+point.y};
 }else{
  const fallback=document.getElementById('mapFallback'),matrix=fallback?.getScreenCTM();
  if(fallback&&matrix){const point=fallback.createSVGPoint();point.x=LOGISTICS_CLOSED_ROAD.x;point.y=LOGISTICS_CLOSED_ROAD.y;const screen=point.matrixTransform(matrix);target={x:screen.x,y:screen.y};}
 }
 if(target){link.setAttribute('x1',cardRect.left+2);link.setAttribute('y1',cardRect.top+cardRect.height*.68);link.setAttribute('x2',target.x);link.setAttribute('y2',target.y);}
 if(video.paused)video.play().catch(()=>{});
}
